mapper.select:
SELECT COUNT(*)
FROM voj_contest_contestants
WHERE contest_id = #{contestId}

SELECT contest_id AS contestId, COUNT(*) AS contestants FROM voj_contest_contestants WHERE contest_id IN
#{contestId}
GROUP BY contest_id

SELECT COUNT(*)
FROM voj_contest_contestants
WHERE contestant_uid = #{contestantUid}

SELECT cc.contestant_uid, u.username, IFNULL(r.score, 0) AS contestant_score, IFNULL(r.used_time, 0) AS contestant_time FROM voj_contest_contestants cc JOIN voj_users u ON u.uid = cc.contestant_uid LEFT JOIN ( SELECT s.uid, SUM(IFNULL(s.submission_judge_score, 0)) AS score, SUM(IFNULL(s.submission_used_time, 0)) AS used_time FROM voj_submissions s JOIN ( SELECT ls.uid, ls.problem_id, MAX(ls.submission_id) AS submission_id FROM voj_contest_submissions lcs JOIN voj_submissions ls ON ls.submission_id = lcs.submission_id WHERE lcs.contest_id = #{contestId}
AND ls.submission_submit_time < #{frozenAt}
GROUP BY ls.uid, ls.problem_id ) last_submission ON last_submission.submission_id = s.submission_id GROUP BY s.uid ) r ON r.uid = cc.contestant_uid WHERE cc.contest_id = #{contestId} ORDER BY contestant_score DESC, contestant_time, cc.contestant_uid LIMIT #{offset}, #{limit}

SELECT cc.contestant_uid, u.username, IFNULL(r.solved, 0) AS contestant_score, IFNULL(r.rejected, 0) AS contestant_time FROM voj_contest_contestants cc JOIN voj_users u ON u.uid = cc.contestant_uid LEFT JOIN ( SELECT first_ac.uid, COUNT(DISTINCT first_ac.problem_id) AS solved, COUNT(rs.submission_id) AS rejected FROM ( SELECT acs.uid, acs.problem_id, MIN(acs.submission_id) AS submission_id FROM voj_contest_submissions accs JOIN voj_submissions acs ON acs.submission_id = accs.submission_id WHERE accs.contest_id = #{contestId} AND acs.submission_judge_result = 'AC'
AND acs.submission_submit_time < #{frozenAt}
GROUP BY acs.uid, acs.problem_id ) first_ac LEFT JOIN ( SELECT rjs.submission_id, rjs.uid, rjs.problem_id FROM voj_contest_submissions rjcs JOIN voj_submissions rjs ON rjs.submission_id = rjcs.submission_id WHERE rjcs.contest_id = #{contestId} AND rjs.submission_judge_result NOT IN ('AC', 'PD', 'CE', 'SE') ) rs ON rs.uid = first_ac.uid AND rs.problem_id = first_ac.problem_id AND rs.submission_id < first_ac.submission_id GROUP BY first_ac.uid ) r ON r.uid = cc.contestant_uid WHERE cc.contest_id = #{contestId} ORDER BY contestant_score DESC, cc.contestant_uid LIMIT #{offset}, #{limit}

SELECT *
FROM voj_contest_contestants
WHERE contest_id = #{contestId}
AND contestant_uid = #{contestantUid}

mapper.delete:
DELETE FROM voj_contest_contestants 
WHERE contest_id = #{contestId} 
AND contestant_uid = #{contestantUid}
